1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  [hidden] { display: none !important; }
10	  body {
11	    margin: 0;
12	    min-height: 100vh;
13	    display: flex;
14	    align-items: center;
15	    justify-content: center;
16	    background: #111827;
17	    color: #e5e7eb;
18	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
19	  }
20	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
21	  .board-wrap { position: relative; }
22	  .board {
23	    display: grid;
24	    grid-template-columns: repeat(10, 28px);
25	    grid-template-rows: repeat(20, 28px);
26	    gap: 1px;
27	    padding: 1px;
28	    background: #1f2937;
29	    border: 2px solid #374151;
30	  }
31	  .cell { width: 28px; height: 28px; background-color: #0b1020; }
32	  .mini {
33	    display: grid;
34	    grid-template-columns: repeat(4, 16px);
35	    grid-template-rows: repeat(2, 16px);
36	    gap: 1px;
37	    margin-bottom: 10px;
38	  }
39	  .mini-cell { width: 16px; height: 16px; background-color: transparent; }
40	  .p-I { background-color: #22d3ee; }
41	  .p-O { background-color: #facc15; }
42	  .p-T { background-color: #a855f7; }
43	  .p-S { background-color: #22c55e; }
44	  .p-Z { background-color: #ef4444; }
45	  .p-J { background-color: #3b82f6; }
46	  .p-L { background-color: #f97316; }
47	  .panel { width: 160px; }
48	  .stat { margin-bottom: 14px; }
49	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9ca3af; }
50	  .stat .value { font-size: 24px; font-weight: 600; font-variant-numeric: tabular-nums; }
51	  .help { font-size: 12px; color: #9ca3af; line-height: 1.6; margin-top: 12px; }
52	  .overlay {
53	    position: absolute;
54	    inset: 0;
55	    display: flex;
56	    flex-direction: column;
57	    align-items: center;
58	    justify-content: center;
59	    background: rgba(17, 24, 39, 0.8);
60	    font-size: 22px;
61	    font-weight: 600;
62	  }
63	  .overlay small { font-size: 13px; font-weight: 400; margin-top: 8px; color: #d1d5db; }
64	</style>
65	</head>
66	<body>
67	<div class="game">
68	  <div class="board-wrap">
69	    <div class="board" id="board" data-testid="board"></div>
70	    <div class="overlay" id="overlay" hidden>Game over<small>Press Enter to play again</small></div>
71	  </div>
72	  <div class="panel">
73	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
74	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
75	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
76	    <div class="stat"><div class="label">Next</div><div id="next"></div></div>
77	    <div class="help">
78	      ← → move<br>
79	      ↑ rotate<br>
80	      ↓ soft drop<br>
81	      Space hard drop<br>
82	      Enter new game
83	    </div>
84	  </div>
85	</div>
86	<script>
87	(function () {
88	  "use strict";
89	
90	  var ROWS = 20;
91	  var COLS = 10;
92	  var PREVIEW = 3;
93	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
94	
95	  // Spawn orientation of each piece inside its rotation box.
96	  var SHAPES = {
97	    I: ["....", "IIII", "....", "...."],
98	    O: ["OO", "OO"],
99	    T: [".T.", "TTT", "..."],
100	    S: [".SS", "SS.", "..."],
101	    Z: ["ZZ.", ".ZZ", "..."],
102	    J: ["J..", "JJJ", "..."],
103	    L: ["..L", "LLL", "..."]
104	  };
105	
106	  var LINE_POINTS = [0, 100, 300, 500, 800];
107	
108	  var state = {
109	    board: [],      // ROWS arrays of COLS chars: "." or a piece letter
110	    current: null,  // { type, matrix, row, col }
111	    next: [],
112	    bag: [],
113	    score: 0,
114	    level: 1,
115	    lines: 0,
116	    status: "running"
117	  };
118	
119	  var timer = null;
120	
121	  // ---------- pieces ----------
122	
123	  function isType(t) { return TYPES.indexOf(t) !== -1; }
124	
125	  function randomType() {
126	    if (state.bag.length === 0) {
127	      var bag = TYPES.slice();
128	      for (var i = bag.length - 1; i > 0; i--) {
129	        var j = Math.floor(Math.random() * (i + 1));
130	        var tmp = bag[i]; bag[i] = bag[j]; bag[j] = tmp;
131	      }
132	      state.bag = bag;
133	    }
134	    return state.bag.pop();
135	  }
136	
137	  function cleanQueue(queue) {
138	    if (!Array.isArray(queue)) return [];
139	    return queue.map(function (t) { return String(t).toUpperCase(); }).filter(isType);
140	  }
141	
142	  function fillPreview() {
143	    while (state.next.length < PREVIEW) state.next.push(randomType());
144	  }
145	
146	  function makeMatrix(type) {
147	    return SHAPES[type].map(function (r) { return r.split(""); });
148	  }
149	
150	  function pieceCells(piece) {
151	    var cells = [];
152	    for (var r = 0; r < piece.matrix.length; r++) {
153	      for (var c = 0; c < piece.matrix[r].length; c++) {
154	        if (piece.matrix[r][c] !== ".") cells.push([piece.row + r, piece.col + c]);
155	      }
156	    }
157	    return cells;
158	  }
159	
160	  function fits(matrix, row, col) {
161	    for (var r = 0; r < matrix.length; r++) {
162	      for (var c = 0; c < matrix[r].length; c++) {
163	        if (matrix[r][c] === ".") continue;
164	        var br = row + r, bc = col + c;
165	        if (br < 0 || br >= ROWS || bc < 0 || bc >= COLS) return false;
166	        if (state.board[br][bc] !== ".") return false;
167	      }
168	    }
169	    return true;
170	  }
171	
172	  // [REQ-001] Spawn the next piece at the top of the board.
173	  function spawn() {
174	    var type = state.next.length ? state.next.shift() : randomType();
175	    if (state.next.length === 0) fillPreview();
176	    var matrix = makeMatrix(type);
177	    var top = 0;
178	    while (matrix[top].every(function (ch) { return ch === "."; })) top++;
179	    var piece = {
180	      type: type,
181	      matrix: matrix,
182	      row: -top,
183	      col: Math.floor((COLS - matrix[0].length) / 2)
184	    };
185	    if (!fits(piece.matrix, piece.row, piece.col)) {
186	      state.current = null;
187	      state.status = "over";
188	      stopTimer();
189	      return;
190	    }
191	    state.current = piece;
192	  }
193	
194	  // ---------- core rules ----------
195	
196	  function clearLines() {
197	    var kept = state.board.filter(function (row) {
198	      return row.some(function (ch) { return ch === "."; });
199	    });
200	    var cleared = ROWS - kept.length;
201	    while (kept.length < ROWS) kept.unshift(emptyRow());
202	    state.board = kept;
203	    if (cleared > 0) {
204	      state.score += LINE_POINTS[cleared] * state.level;
205	      state.lines += cleared;
206	      state.level = Math.floor(state.lines / 10) + 1;
207	    }
208	  }
209	
210	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next one.
211	  function lockPiece() {
212	    var p = state.current;
213	    pieceCells(p).forEach(function (cell) {
214	      state.board[cell[0]][cell[1]] = p.type;
215	    });
216	    state.current = null;
217	    clearLines();
218	    spawn();
219	  }
220	
221	  function tryMove(dr, dc) {
222	    var p = state.current;
223	    if (!p || !fits(p.matrix, p.row + dr, p.col + dc)) return false;
224	    p.row += dr;
225	    p.col += dc;
226	    return true;
227	  }
228	
229	  // [REQ-001] One gravity step: fall one row, or lock when the piece cannot fall.
230	  // Used by the real timer, by tick(n) and by soft drop.
231	  function gravityStep() {
232	    if (state.status !== "running" || !state.current) return;
233	    if (!tryMove(1, 0)) lockPiece();
234	  }
235	
236	  function rotate() {
237	    var p = state.current;
238	    if (!p) return;
239	    var size = p.matrix.length;
240	    var rotated = [];
241	    for (var r = 0; r < size; r++) {
242	      rotated.push([]);
243	      for (var c = 0; c < size; c++) rotated[r].push(p.matrix[size - 1 - c][r]);
244	    }
245	    var kicks = [0, -1, 1, -2, 2];
246	    for (var i = 0; i < kicks.length; i++) {
247	      if (fits(rotated, p.row, p.col + kicks[i])) {
248	        p.matrix = rotated;
249	        p.col += kicks[i];
250	        return;
251	      }
252	    }
253	  }
254	
255	  // [REQ-001] Player actions.
256	  function input(action) {
257	    if (state.status !== "running" || !state.current) return;
258	    switch (action) {
259	      case "left": tryMove(0, -1); break;
260	      case "right": tryMove(0, 1); break;
261	      case "softDrop": gravityStep(); break;
262	      case "hardDrop":
263	        while (tryMove(1, 0)) {}
264	        lockPiece();
265	        break;
266	      case "rotate": rotate(); break;
267	      default: return;
268	    }
269	    render();
270	    restartTimerIfNeeded();
271	  }
272	
273	  // ---------- timer ----------
274	
275	  function gravityInterval() {
276	    return Math.max(100, 1000 - (state.level - 1) * 90);
277	  }
278	
279	  function stopTimer() {
280	    if (timer !== null) { clearTimeout(timer); timer = null; }
281	  }
282	
283	  function startTimer() {
284	    stopTimer();
285	    if (state.status !== "running") return;
286	    timer = setTimeout(function () {
287	      timer = null;
288	      gravityStep();
289	      render();
290	      startTimer();
291	    }, gravityInterval());
292	  }
293	
294	  function restartTimerIfNeeded() {
295	    if (state.status === "running" && timer === null) startTimer();
296	  }
297	
298	  // ---------- setup ----------
299	
300	  function emptyRow() {
301	    var row = [];
302	    for (var c = 0; c < COLS; c++) row.push(".");
303	    return row;
304	  }
305	
306	  // [REQ-001] Start a fresh game, optionally with a fixed piece order.
307	  function newGame(queue) {
308	    state.board = [];
309	    for (var r = 0; r < ROWS; r++) state.board.push(emptyRow());
310	    state.bag = [];
311	    state.score = 0;
312	    state.level = 1;
313	    state.lines = 0;
314	    state.status = "running";
315	    state.current = null;
316	    var q = cleanQueue(queue);
317	    state.next = q;
318	    if (q.length === 0) fillPreview();
319	    spawn();
320	    render();
321	    startTimer();
322	  }
323	
324	  // ---------- rendering (synchronous) ----------
325	
326	  var boardEl = document.getElementById("board");
327	  var nextEl = document.getElementById("next");
328	  var scoreEl = document.getElementById("score");
329	  var levelEl = document.getElementById("level");
330	  var linesEl = document.getElementById("lines");
331	  var overlayEl = document.getElementById("overlay");
332	  var cellEls = [];
333	
334	  (function buildBoard() {
335	    for (var r = 0; r < ROWS; r++) {
336	      cellEls.push([]);
337	      for (var c = 0; c < COLS; c++) {
338	        var el = document.createElement("div");
339	        el.className = "cell";
340	        el.setAttribute("data-testid", "cell");
341	        el.setAttribute("data-row", String(r));
342	        el.setAttribute("data-col", String(c));
343	        el.setAttribute("data-filled", "false");
344	        el.setAttribute("data-piece", "");
345	        boardEl.appendChild(el);
346	        cellEls[r].push(el);
347	      }
348	    }
349	  })();
350	
351	  function paintCell(el, type) {
352	    el.className = type ? "cell p-" + type : "cell";
353	    el.setAttribute("data-filled", type ? "true" : "false");
354	    el.setAttribute("data-piece", type || "");
355	  }
356	
357	  function renderPreview() {
358	    nextEl.textContent = "";
359	    state.next.slice(0, PREVIEW).forEach(function (type) {
360	      var grid = document.createElement("div");
361	      grid.className = "mini";
362	      var rows = SHAPES[type].filter(function (r) { return r.indexOf(type) !== -1; });
363	      for (var r = 0; r < 2; r++) {
364	        for (var c = 0; c < 4; c++) {
365	          var cell = document.createElement("div");
366	          var ch = rows[r] ? rows[r].charAt(c) : ".";
367	          cell.className = ch === type ? "mini-cell p-" + type : "mini-cell";
368	          cell.setAttribute("data-piece", ch === type ? type : "");
369	          grid.appendChild(cell);
370	        }
371	      }
372	      nextEl.appendChild(grid);
373	    });
374	  }
375	
376	  // [REQ-001] Draw the whole game state into the DOM, immediately.
377	  function render() {
378	    var drawn = state.board.map(function (row) { return row.slice(); });
379	    if (state.current) {
380	      var type = state.current.type;
381	      pieceCells(state.current).forEach(function (cell) {
382	        drawn[cell[0]][cell[1]] = type;
383	      });
384	    }
385	    for (var r = 0; r < ROWS; r++) {
386	      for (var c = 0; c < COLS; c++) {
387	        var ch = drawn[r][c];
388	        paintCell(cellEls[r][c], ch === "." ? "" : ch);
389	      }
390	    }
391	    scoreEl.textContent = String(state.score);
392	    levelEl.textContent = String(state.level);
393	    linesEl.textContent = String(state.lines);
394	    overlayEl.hidden = state.status !== "over";
395	    renderPreview();
396	  }
397	
398	  // ---------- keyboard ----------
399	
400	  document.addEventListener("keydown", function (e) {
401	    var map = {
402	      ArrowLeft: "left",
403	      ArrowRight: "right",
404	      ArrowDown: "softDrop",
405	      ArrowUp: "rotate",
406	      " ": "hardDrop"
407	    };
408	    if (e.key === "Enter") {
409	      e.preventDefault();
410	      newGame();
411	      return;
412	    }
413	    if (map[e.key]) {
414	      e.preventDefault();
415	      input(map[e.key]);
416	    }
417	  });
418	
419	  // ---------- test control surface ----------
420	
421	  // [REQ-001]
422	  window.__tetris = {
423	    newGame: function (queue) { newGame(queue); },
424	    setQueue: function (queue) {
425	      state.next = cleanQueue(queue);
426	      render();
427	    },
428	    setBoard: function (rows) {
429	      var board = [];
430	      for (var r = 0; r < ROWS; r++) {
431	        var line = rows && typeof rows[r] === "string" ? rows[r] : "";
432	        var row = [];
433	        for (var c = 0; c < COLS; c++) {
434	          var ch = line.charAt(c);
435	          row.push(isType(ch) ? ch : ".");
436	        }
437	        board.push(row);
438	      }
439	      state.board = board;
440	      render();
441	    },
442	    tick: function (n) {
443	      var steps = n === undefined ? 1 : n;
444	      for (var i = 0; i < steps; i++) gravityStep();
445	      render();
446	    },
447	    input: function (action) { input(action); },
448	    getBoard: function () {
449	      return state.board.map(function (row) { return row.join(""); });
450	    },
451	    getState: function () {
452	      return {
453	        current: state.current
454	          ? { type: state.current.type, cells: pieceCells(state.current) }
455	          : null,
456	        next: state.next.slice(),
457	        score: state.score,
458	        level: state.level,
459	        lines: state.lines,
460	        status: state.status
461	      };
462	    }
463	  };
464	
465	  newGame();
466	})();
467	</script>
468	</body>
469	</html>
